using System;

namespace GravityWells.Core
{
    // Which background tracks exist and how loud and how fast each plays. Every track is generated by our
    // own code, so there is no third-party audio in the game.
    public enum MusicTrack
    {
        None,
        Orbit,   // the game's own loop: a slow plucked motif over a drone, with a falling slide
    }

    public static class MusicLibrary
    {
        public const int SampleRate = 22050;

        // How much the tense tracks speed up and swell as the pressure (0..1) rises. Orbit never does: it is
        // the calm under the puzzle, and a puzzle with no clock has no pressure to answer.
        public const float MaxPitchRise = 0.12f;
        public const float VolumeFloor = 0.85f;

        // Builds a track's loop (slow: run it on a background thread).
        public static float[] Generate(MusicTrack track)
        {
            switch (track)
            {
                case MusicTrack.Orbit: return OrbitMusic.Generate(SampleRate);
                default: return new float[0];
            }
        }

        // The loudness a track plays at. Tracks are normalised to the same loudness already, so this only
        // sets how far the music sits behind the game's own sounds.
        public static float BaseVolume(MusicTrack track)
        {
            switch (track)
            {
                case MusicTrack.Orbit: return 0.55f;
                default: return 0f;
            }
        }

        public static bool RespondsToPressure(MusicTrack track) => false;

        // Playback speed: normal, rising with the pressure for tracks that respond to pressure.
        public static float PitchFor(MusicTrack track, float pressure) =>
            RespondsToPressure(track) ? 1f + MaxPitchRise * Clamp01(pressure) : 1f;

        public static float VolumeFor(MusicTrack track, float pressure)
        {
            float volume = BaseVolume(track);
            return RespondsToPressure(track) ? volume * (VolumeFloor + (1f - VolumeFloor) * Clamp01(pressure)) : volume;
        }

        private static float Clamp01(float value) => Math.Max(0f, Math.Min(1f, value));
    }
}
